@staticmethod
def load(data: dict) -> WorkSpace:
    """Inverse of :meth:`dump` (tree, parent re-wired)."""

    by_id: dict[str, WorkSpace] = {}

    def build(node: dict) -> WorkSpace:
        ws = WorkSpace(id=node["id"], label=node["label"], lifetime=Lifetime(node["lifetime"]), irs=node.get("irs", {}))
        by_id[ws.id] = ws
        for cnode in node.get("children", []):
            ws.add_child(build(cnode))
        return ws

    root = build(data)
    # parent pointers are re-wired by add_child during build (root has
    # parent=None — the dump's per-node parent field mirrors that)
    del by_id
    return root

