"""E4.1 constraint core — a generic n-dimensional logical-grid solver.

The core knows NOTHING about Einstein's riddle. A ``PuzzleSpec`` is data:
``houses`` positions, an ordered list of ``Dimension``s (each with a
declared term vocabulary and, optionally, terms the system does not KNOW —
"typed but unknown", rendered as typed placeholders), and a list of
``Clue``s in four canonical forms:

- ``At(dim, term, pos)``       — the term sits at position ``pos``
- ``Pair(da, ta, db, tb)``     — ta and tb sit at the SAME position
- ``Left(da, ta, db, tb)``     — ta is IMMEDIATELY left of tb (pos + 1)
- ``Next(da, ta, db, tb)``     — ta and tb are ADJACENT positions

Every dimension is a bijection between terms and positions ("all different":
each term used exactly once, each position occupied by exactly one term).

The solver is deterministic:

1. **Forward chaining** — candidate-position domains per (dim, term),
   narrowed by clues (in declared order) and by the two all-different
   inferences (hidden single / naked single), to a fixpoint. Every
   narrowing is LOGGED: ``(variable, removed_positions, cause)`` where
   ``cause`` is a clue or an axiom — that log IS the proof chain.
2. **Backtracking** — when consistent but not complete, branch on the
   smallest domain (deterministic tie-break), values ascending.
3. **Uniqueness** — continue the search after the first solution; at most
   ``cap`` solutions are enumerated (2 suffices for the uniqueness proof).
4. **Contradiction certificate** — on wipeout, the fired causes are
   collected and inclusion-minimalised by deletion re-testing (any member
   removed makes the reduced set satisfiable).
5. **Degradation machinery** (the E4.1 arms):
   - hidden terms → placeholders; :meth:`Solution.gaps` states exactly which
     cells are typed but unnameable (the "I need x piece of information"
     honesty contract);
   - :func:`undetermined_facts` — per variable, the positions that vary
     across all solutions (missing-clue arm: says EXACTLY what is
     undetermined);
   - :func:`resolving_facts` — the canonical ``At`` facts that, added,
     restore a unique consistent solution (missing-clue arm: names EXACTLY
     what would fix it).
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

__all__ = [
    "At",
    "Clue",
    "Contradiction",
    "Dimension",
    "Gap",
    "Left",
    "Next",
    "Pair",
    "PuzzleSpec",
    "Solution",
    "SolveReport",
    "all_satisfiable",
    "minimal_certificate",
    "resolving_facts",
    "solve",
    "undetermined_facts",
]

#: Inference axioms (never deletable from a certificate; stated, not listed).
AXIOM_ALLDIFF = "all-different: every dimension is a bijection terms<->positions"


# ── spec (data, not code) ─────────────────────────────────────────────────–


@dataclass(frozen=True)
class Dimension:
    """One row of the grid: a name, its full vocabulary, and the terms the
    system does NOT know (rendered as typed placeholders ``<name>:u<k>``)."""

    name: str
    terms: tuple[str, ...]
    hidden: frozenset[str] = frozenset()

    def placeholders(self) -> dict[str, str]:
        """true term -> placeholder name, for hidden terms (sorted order)."""

        out: dict[str, str] = {}
        for k, term in enumerate(sorted(t for t in self.terms if t in self.hidden), 1):
            out[term] = f"{self.name}:u{k}"
        return out

    def visible(self) -> tuple[str, ...]:
        """The vocabulary the solver is allowed to NAME (known + placeholders)."""

        ph = self.placeholders()
        return tuple(ph[t] if t in ph else t for t in self.terms)


@dataclass(frozen=True)
class At:
    dim: str
    term: str
    pos: int

    @property
    def text(self) -> str:
        return f"{self.term} is at {self.dim} position {self.pos}"


@dataclass(frozen=True)
class Pair:
    dim_a: str
    term_a: str
    dim_b: str
    term_b: str

    @property
    def text(self) -> str:
        return f"{self.term_a} ({self.dim_a}) is at the same position as {self.term_b} ({self.dim_b})"


@dataclass(frozen=True)
class Left:
    dim_a: str
    term_a: str
    dim_b: str
    term_b: str

    @property
    def text(self) -> str:
        return f"{self.term_a} ({self.dim_a}) is immediately left of {self.term_b} ({self.dim_b})"


@dataclass(frozen=True)
class Next:
    dim_a: str
    term_a: str
    dim_b: str
    term_b: str

    @property
    def text(self) -> str:
        return f"{self.term_a} ({self.dim_a}) is next to {self.term_b} ({self.dim_b})"


Clue = At | Pair | Left | Next


@dataclass(frozen=True)
class PuzzleSpec:
    """The whole puzzle as data: positions, dimensions, clues (in order).
    New puzzle = new spec; the core code never changes (arm E is this)."""

    houses: int
    dimensions: tuple[Dimension, ...]
    clues: tuple[Clue, ...]

    @property
    def dim_order(self) -> dict[str, int]:
        return {d.name: i for i, d in enumerate(self.dimensions)}

    def dim(self, name: str) -> Dimension:
        try:
            return next(d for d in self.dimensions if d.name == name)
        except StopIteration:
            raise KeyError(f"unknown dimension {name!r}") from None

    def visible_terms(self, dim: str) -> tuple[str, ...]:
        """The vocabulary the solver may use for this dimension."""

        return self.dim(dim).visible()

    def with_clues(self, clues: tuple[Clue, ...]) -> PuzzleSpec:
        return PuzzleSpec(self.houses, self.dimensions, clues)

    def with_hidden(self, dim: str, hidden: frozenset[str]) -> PuzzleSpec:
        dims = tuple(d if d.name != dim else Dimension(d.name, d.terms, hidden) for d in self.dimensions)
        return PuzzleSpec(self.houses, dims, self.clues)


# ── derivation (the proof chain) ──────────────────────────────────────────


@dataclass(frozen=True)
class ProofStep:
    """One logged narrowing: variable (dim, term), removed positions, cause."""

    dim: str
    term: str
    removed: tuple[int, ...]
    cause: str  # clue text (+ form tag) or an axiom


@dataclass(frozen=True)
class Contradiction:
    """A wipeout: the fired causes (clues/axioms) and the exact reason."""

    clue_ids: tuple[int, ...]
    reason: str


# ── propagation ────────────────────────────────────────────────────────────


def _clause_cause(clue: Clue, idx: int) -> str:
    return f"clue#{idx}: {clue.text}"


def _propagate_once(spec: PuzzleSpec, doms: dict[tuple[str, str], frozenset[int]], log: list[ProofStep]) -> bool:
    """One pass of clause application + all-diff inferences. Returns True if
    anything changed. Deterministic order: clues in spec order, then each
    dimension (spec order) hidden-single then naked-single, terms sorted."""

    changed = False

    def shrink(key: tuple[str, str], keep: frozenset[int], cause: str) -> None:
        nonlocal changed
        dom = doms[key]
        removed = dom - keep
        if removed:
            doms[key] = keep & dom
            if doms[key] != dom:
                log.append(ProofStep(key[0], key[1], tuple(sorted(removed)), cause))
                changed = True

    for idx, clue in enumerate(spec.clues):
        if isinstance(clue, At):
            shrink((clue.dim, clue.term), frozenset({clue.pos}), _clause_cause(clue, idx))
        elif isinstance(clue, Pair):
            ka, kb = (clue.dim_a, clue.term_a), (clue.dim_b, clue.term_b)
            if ka in doms and kb in doms:
                inter = doms[ka] & doms[kb]
                shrink(ka, inter, _clause_cause(clue, idx))
                shrink(kb, inter, _clause_cause(clue, idx))
        elif isinstance(clue, Left):
            ka, kb = (clue.dim_a, clue.term_a), (clue.dim_b, clue.term_b)
            if ka in doms and kb in doms:
                ok_a = frozenset(p for p in doms[ka] if p + 1 in doms[kb])
                shrink(ka, ok_a, _clause_cause(clue, idx))
                ok_b = frozenset(p for p in doms[kb] if p - 1 in doms[ka])
                shrink(kb, ok_b, _clause_cause(clue, idx))
        elif isinstance(clue, Next):
            ka, kb = (clue.dim_a, clue.term_a), (clue.dim_b, clue.term_b)
            if ka in doms and kb in doms:
                ok_a = frozenset(p for p in doms[ka] if any(abs(p - q) == 1 for q in doms[kb]))
                shrink(ka, ok_a, _clause_cause(clue, idx))
                ok_b = frozenset(p for p in doms[kb] if any(abs(p - q) == 1 for q in doms[ka]))
                shrink(kb, ok_b, _clause_cause(clue, idx))

    for d in spec.dimensions:
        terms = list(d.visible())
        pos = frozenset(range(1, spec.houses + 1))
        # hidden single: a term with one candidate occupies that position.
        for t in terms:
            dom = doms[(d.name, t)]
            if len(dom) == 1:
                p = next(iter(dom))
                for t2 in terms:
                    if t2 != t and p in doms[(d.name, t2)]:
                        shrink((d.name, t2), frozenset(dom - {p}), f"axiom: {AXIOM_ALLDIFF} ({d.name})")
        # naked single: a position only one term can fill takes that term.
        for p in range(1, spec.houses + 1):
            candidates = [t for t in terms if p in doms[(d.name, t)]]
            if len(candidates) == 1:
                for t2 in terms:
                    if t2 != candidates[0] and p in doms[(d.name, t2)]:
                        shrink((d.name, t2), frozenset(doms[(d.name, t2)] - {p}), f"axiom: {AXIOM_ALLDIFF} ({d.name})")
    return changed


def _to_fixpoint(spec: PuzzleSpec, doms: dict[tuple[str, str], frozenset[int]], log: list[ProofStep]) -> None:
    """Iterate until stable or wipeout.

    Raises:
        Contradiction: a domain emptied; carries the clue ids that fired
        (the certificate seed).
    """

    fired: set[int] = set()
    last_reason = ""
    while _propagate_once(spec, doms, log):
        for (dim, _term), dom in doms.items():
            if not dom:
                # the most recent log entry naming this variable caused it
                last = [s for s in reversed(log) if s.dim == dim and s.term == _term][0]
                cid = None
                for step in reversed(log):
                    if step.dim == dim and step.term == _term and step.cause.startswith("clue#"):
                        cid = int(step.cause.split(":")[0].split("#")[1])
                        break
                fired.update(i for i, c in enumerate(spec.clues) if i == (cid if cid is not None else -1))
                if last.cause.startswith("clue#"):
                    fired.add(int(last.cause.split(":")[0].split("#")[1]))
                raise Contradiction(clue_ids=tuple(sorted(fired)), reason=f"{dim}/{_term}: {last.cause}")
    _ = last_reason
    # post-hoc wipeout scan (two clues can jointly empty a domain without the
    # second being the most recent step): any empty domain is still a contradiction
    for (dim, term), dom in doms.items():
        if not dom:
            raise Contradiction(clue_ids=tuple(sorted(fired)), reason=f"{dim}/{term}: domain empty at fixpoint")


# ── search (deterministic backtracking) ────────────────────────────────────


@dataclass
class Solution:
    """One complete grid: (dim, term) -> position, its proof chain, the
    search decisions that produced it, and its typed-but-unknown gaps."""

    assignment: dict[tuple[str, str], int]
    proof: dict[tuple[str, str], tuple[ProofStep, ...]]
    branches: tuple[tuple[str, str, int], ...]

    def pos(self, dim: str, term: str) -> int:
        return self.assignment[(dim, term)]

    def cell(self, pos: int, spec: PuzzleSpec) -> dict[str, str]:
        """The fully-named (in visible vocabulary) occupant of a position."""

        return {
            d.name: next(t for t in d.visible() if self.assignment[(d.name, t)] == pos)
            for d in spec.dimensions
        }

    def gaps(self, spec: PuzzleSpec) -> tuple[Gap, ...]:
        """Every cell the solver occupies but CANNOT name (typed unknowns)."""

        out: list[Gap] = []
        for d in spec.dimensions:
            ph = d.placeholders()
            for term, name in sorted(ph.items()):
                p = self.assignment[(d.name, name)]
                out.append(
                    Gap(
                        dim=d.name,
                        placeholder=name,
                        pos=p,
                        cell=self.cell(p, spec),
                        statement=(
                            f"the {d.name} at position {p} is a known {d.name}-type member but I "
                            f"have no term for it; providing its name (one of the {d.name} "
                            f"vocabulary I was not given) would let me name this cell"
                        ),
                    )
                )
        return tuple(out)

    def as_grid(self, spec: PuzzleSpec) -> list[dict[str, str]]:
        """Human layout: row per position (1..houses), dim -> visible name."""

        return [self.cell(p, spec) for p in range(1, spec.houses + 1)]


@dataclass(frozen=True)
class Gap:
    """A typed-but-unnameable cell (arm B): the honest 'I need x' statement."""

    dim: str
    placeholder: str
    pos: int
    cell: dict[str, str]
    statement: str


def _initial_domains(spec: PuzzleSpec) -> dict[tuple[str, str], frozenset[int]]:
    full = frozenset(range(1, spec.houses + 1))
    return {(d.name, t): full for d in spec.dimensions for t in d.visible()}


def _branch_var(spec: PuzzleSpec, doms: dict[tuple[str, str], frozenset[int]]) -> tuple[str, str] | None:
    free = {k: v for k, v in doms.items() if len(v) > 1}
    if not free:
        return None
    return min(free, key=lambda k: (len(doms[k]), spec.dim_order[k[0]], k[1]))


def _search(
    spec: PuzzleSpec,
    doms: dict[tuple[str, str], frozenset[int]],
    log: list[ProofStep],
    branches: list[tuple[str, str, int]],
    solutions: list[Solution],
    cap: int,
) -> None:
    if len(solutions) >= cap:
        return
    v = _branch_var(spec, doms)
    if v is None:
        if all(len(d) == 1 for d in doms.values()):
            sol = {k: next(iter(d)) for k, d in doms.items()}
            proof = {
                k: tuple(s for s in log if s.dim == k[0] and s.term == k[1])
                for k in sol
            }
            solutions.append(Solution(assignment=sol, proof=proof, branches=tuple(branches)))
        return
    for value in sorted(doms[v]):
        doms[v] = frozenset({value})
        log.append(ProofStep(v[0], v[1], tuple(sorted(doms_all_except(spec, doms, v) - {value})), "search: branch"))
        branches.append((v[0], v[1], value))
        try:
            snap_log = list(log)
            _to_fixpoint(spec, doms, log)
            _search(spec, doms, log, branches, solutions, cap)
        except Contradiction:
            log[:] = snap_log
            doms[v] = frozenset(range(1, spec.houses + 1))
        else:
            log[:] = snap_log
        finally:
            branch = branches.pop()
            doms[v] = frozenset(range(1, spec.houses + 1))
    _ = branch_var_guard


def _doms_all_except(spec: PuzzleSpec, doms: dict[tuple[str, str], frozenset[int]], v: tuple[str, str],) -> frozenset[int]:
    return frozenset(range(1, spec.houses + 1))


# keep a stable name for the (intentionally trivial) helper above
branch_var_guard = None


@dataclass
class SolveReport:
    """The solver's full, deterministic answer to one spec."""

    status: str  # "solved" | "no_solution" | "underdetermined"
    solutions: list[Solution]
    unique: bool
    contradiction: Contradiction | None
    cap: int


def solve(spec: PuzzleSpec, cap: int = 2) -> SolveReport:
    """Forward-chain + deterministic backtracking; up to ``cap`` solutions."""

    doms = _initial_domains(spec)
    log: list[ProofStep] = []
    try:
        _to_fixpoint(spec, doms, log)
    except Contradiction as c:
        return SolveReport(status="no_solution", solutions=[], unique=False, contradiction=c, cap=cap)
    solutions: list[Solution] = []
    _search(spec, doms, log, [], solutions, cap)
    if not solutions:
        return SolveReport(status="no_solution", solutions=[], unique=False, contradiction=None, cap=cap)
    if len(solutions) >= cap:
        return SolveReport(
            status="underdetermined", solutions=solutions, unique=False, contradiction=None, cap=cap
        )
    return SolveReport(status="solved", solutions=solutions, unique=len(solutions) == 1, contradiction=None, cap=cap)


def all_satisfiable(spec: PuzzleSpec, cap: int = 400) -> SolveReport:
    """Enumerate up to ``cap`` solutions (the missing-clue / certificate arms)."""

    return solve(spec, cap=cap)


# ── contradiction certificates (arm D) ─────────────────────────────────────


def minimal_certificate(spec: PuzzleSpec, seed_clue_ids: tuple[int, ...]) -> list[int]:
    """Inclusion-minimal subset of the *given* clue ids (clues only; the
    all-different axiom is a stated premise, never listed) that is still
    unsatisfiable. Deletion order is deterministic (ascending id)."""

    core = sorted(seed_clue_ids)
    for cid in list(core):
        without = spec.with_clues(tuple(c for i, c in enumerate(spec.clues) if i != cid))
        if solve(without, cap=1).status == "no_solution":
            core.remove(cid)
    return core


# ── degradation machinery (arms B / C) ─────────────────────────────────────


def undetermined_facts(solutions: list[Solution]) -> dict[tuple[str, str], tuple[int, ...]]:
    """Per (dim, term): the positions it occupies ACROSS all solutions.
    A tuple of length 1 is determined; >1 says EXACTLY what is undetermined
    and against which alternatives (arm C output)."""

    out: dict[tuple[str, str], set[int]] = {}
    for sol in solutions:
        for key, p in sol.assignment.items():
            out.setdefault(key, set()).add(p)
    return {k: tuple(sorted(v)) for k, v in out.items() if len(v) > 1 or True}


def resolving_facts(spec: PuzzleSpec, dropped_count: int) -> list[tuple[Clue, SolveReport]]:
    """Every canonical ``At`` fact over a currently-undetermined variable
    that (a) is consistent with the spec and (b) restores uniqueness —
    i.e. names EXACTLY what would fix a missing clue (arm C output)."""

    base = all_satisfiable(spec, cap=200)
    if base.unique or not base.solutions:
        return []
    vary = {k: v for k, v in undetermined_facts(base.solutions).items() if len(v) > 1}
    out: list[tuple[Clue, SolveReport]] = []
    for (dim, term) in sorted(vary, key=lambda k: (spec.dim_order[k[0]], k[1])):
        for pos in vary[(dim, term)]:
            fact = At(dim, term, pos)
            rep = solve(spec.with_clues(spec.clues + (fact,)), cap=2)
            if rep.status == "solved" and rep.unique:
                out.append((fact, rep))
    _ = dropped_count
    return out

"""E4.1 constraint core — a generic n-dimensional logical-grid solver.

The core knows NOTHING about Einstein's riddle. A ``PuzzleSpec`` is data:
``houses`` positions, an ordered list of ``Dimension``s (each with a
declared term vocabulary and, optionally, terms the system does not KNOW —
"typed but unknown", rendered as typed placeholders ``<name>:u<k>``), and a
list of ``Clue``s in four canonical forms:

- ``At(dim, term, pos)``       — the term sits at position ``pos``
- ``Pair(da, ta, db, tb)``     — ta and tb sit at the SAME position
- ``Left(da, ta, db, tb)``     — ta is immediately left of tb (pos + 1)
- ``Next(da, ta, db, tb)``     — ta and tb are at ADJACENT positions

Every dimension is a bijection between terms and positions (the stated
axiom "all different": each term used exactly once, each position occupied
by exactly one term).

The solver is deterministic:

1. **Forward chaining** — candidate-position domains per (dim, term),
   narrowed by clues (in declared order) and by the two all-different
   inferences (hidden single / naked single), to a fixpoint. Every
   narrowing is LOGGED: ``(variable, removed_positions, cause)`` where
   ``cause`` names the clue or the axiom. For any solution, the log of its
   search path, replayed from the initial domains, reproduces the
   assignment exactly — that IS the proof chain.
2. **Backtracking** — when consistent but not complete, branch on the
   smallest domain (deterministic tie-break: dimension order, term order),
   values ascending.
3. **Uniqueness** — the search continues after the first solution; up to
   ``cap`` solutions are enumerated (2 suffices to prove/refute uniqueness).
4. **Contradiction certificate** — on domain wipeout, the clue ids that
   fired before the wipeout are collected and inclusion-minimalised by
   deletion re-testing: :func:`minimal_certificate` returns a clue set
   that is unsatisfiable and becomes satisfiable if any member is removed
   (the all-different axiom is a stated premise, never listed).
5. **Degradation machinery** (the E4.1 arms):
   - hidden terms become typed placeholders; ``Solution.gaps()`` states
     EXACTLY which cells are occupied but unnameable (the honest "I need x
     piece of information" contract, arm B);
   - :func:`undetermined_facts` — per variable, the positions it occupies
     across ALL solutions of an under-determined spec (arm C: says exactly
     what is undetermined, against which alternatives);
   - :func:`resolving_facts` — the canonical ``At`` facts over
     undetermined variables that, added, restore a unique consistent
     solution (arm C: names exactly what would fix it).
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Callable

__all__ = [
    "At",
    "Clue",
    "Contradiction",
    "DIMENSION_COUNT",
    "Dimension",
    "Gap",
    "Left",
    "Next",
    "Pair",
    "PuzzleSpec",
    "Solution",
    "SolveReport",
    "minimal_certificate",
    "resolving_facts",
    "solve",
    "undetermined_facts",
]

#: The one structural axiom (stated in every verdict; never listed as a clue).
AXIOM_ALLDIFF = "all-different: each dimension is a bijection terms<->positions"

#: Maximum solutions enumerated under degradation (arm C / certificates).
DIMENSION_COUNT = 400


# ── the spec (data, not code) ──────────────────────────────────────────────


@dataclass(frozen=True)
class Dimension:
    """One row of the grid: a name, its full vocabulary, and the terms the
    system does NOT know (rendered as typed placeholders ``<name>:u<k>``)."""

    name: str
    terms: tuple[str, ...]
    hidden: frozenset[str] = frozenset()

    def placeholders(self) -> dict[str, str]:
        """true term -> placeholder name for hidden terms (sorted order)."""

        out: dict[str, str] = {}
        for k, term in enumerate(sorted(t for t in self.terms if t in self.hidden), 1):
            out[term] = f"{self.name}:u{k}"
        return out

    def visible(self) -> tuple[str, str]:
        """The vocabulary the solver is allowed to NAME (known + placeholders),
        in declared term order."""

        ph = self.placeholders()
        return tuple(ph[t] if t in ph else t for t in self.terms)


@dataclass(frozen=True)
class At:
    """The term sits at position ``pos`` (1-based, left to right)."""

    dim: str
    term: str
    pos: int

    @property
    def text(self) -> str:
        return f"{self.term} ({self.dim}) is at position {self.pos}"


@dataclass(frozen=True)
class Pair:
    """The two terms sit at the SAME position."""

    dim_a: str
    term_a: str
    dim_b: str
    term_b: str

    @property
    def text(self) -> str:
        return f"{self.term_a} ({self.dim_a}) is with {self.term_b} ({self.dim_b})"


@dataclass(frozen=True)
class Left:
