def _search(
    spec: PuzzleSpec,
    doms: dict[tuple[str, str], frozenset[int]],
    log: list[ProofStep],
    branches: list[tuple[str, str, int]],
    solutions: list[Solution],
    cap: int,
) -> None:
    if len(solutions) >= cap:
        return
    v = _branch_var(spec, doms)
    if v is None:
        if all(len(d) == 1 for d in doms.values()):
            assignment = {k: next(iter(d)) for k, d in doms.items()}
            proof = {k: tuple(s for s in log if (s.dim, s.term) == k) for k in assignment}
            solutions.append(Solution(assignment=assignment, proof=proof, branches=tuple(branches)))
        return
    saved = doms[v]
    for value in sorted(saved):
        if len(solutions) >= cap:
            break
        doms[v] = frozenset({value})
        log.append(ProofStep(v[0], v[1], tuple(sorted(saved - frozenset({value}))), f"search: branch {value}"))
        branches.append((v[0], v[1], value))
        snapshot = list(log)
        try:
            _to_fixpoint(spec, doms, log)
            _search(spec, doms, log, branches, solutions, cap)
        except Contradiction:
            pass
        finally:
            log[:] = snapshot
            branches.pop()
            doms[v] = saved


