"""T1 game kernel — the scheduler: a deterministic round driver.

Round semantics (fixed, seeded, synchronous):

    for each round:  channel.new_round()
        for each player in turn order:
            inbox <- channel.take_inbox(player); agent.merge_inbox(round)
            action, rejection = agent.act_on(round, transcript)
            execute: Say -> channel.deliver (budget+corruption),
                     Reveal -> broadcast fact deltas (same channel),
                     Commit -> recorded (last wins), Pass -> recorded
            view-isolation invariant re-checked EVERY turn
            (recorded in the report: a "leaky view" fails the suite,
             E3.7 style)

Messages are delivered during round n and OBSERVED at the start of
round n+1 (no within-round ordering bias). Everything derives from
``(spec, policies, seed)`` — two runs of the same game are
bit-identical (the determinism hash in the report proves it).
"""

from __future__ import annotations

import hashlib
import json
import random
import warnings
from dataclasses import dataclass
from typing import Any, Callable

from kainos.game.agent import Agent, fact_delta_for, game_ts
from kainos.game.actions import Action, Commit, Pass, Reveal, Say, action_kind
from kainos.game.audit import tom_audit
from kainos.game.channel import Channel
from kainos.game.spec import GameSpec

__all__ = ["Game", "ScorerFn"]

#: ScorerFn: (final commits, game) -> scores block (pure, deterministic).
ScorerFn = Callable[[dict[str, dict[str, Any]], Game], dict[str, Any]]


def _serialize_action(action: Action) -> dict[str, Any]:
    if isinstance(action, Say):
        out: dict[str, Any] = {"kind": "say", "receiver": action.receiver, "deltas": []}
        for d in action.deltas:
            a = d.assertion
            out["deltas"].append(
                {
                    "id": a.id,
                    "subject": a.subject.id,
                    "relation": a.relation.id,
                    "object": a.object_id,
                    "source": a.provenance.source.uri if a.provenance and a.provenance.source else None,
                    "timestamp": d.timestamp,
                }
            )
        return out
    if isinstance(action, Reveal):
        return {"kind": "reveal", "fact_ids": list(action.fact_ids)}
    if isinstance(action, Commit):
        return {"kind": "commit", "payload": dict(action.payload)}
    if isinstance(action, Pass):
        return {"kind": "pass"}
    raise TypeError(f"unknown action {action!r}")


@dataclass
class Game:
    """A concrete game: spec + agents + seed. ``run`` is pure in its
    inputs apart from the (optionally requested) report file write."""

    spec: GameSpec
    agents: dict[str, Agent]
    seed: int
    scorer: ScorerFn | None = None

    def _make_scorer(self) -> ScorerFn:
        if self.scorer is not None:
            return self.scorer

        def default(commits: dict[str, dict[str, Any]], game: Game) -> dict[str, Any]:
            return {"n_commits": len(commits)}

        return default

    def run(self, write: bool = True, out_dir: "str | Any" = None) -> dict[str, Any]:
        rng = random.Random(self.seed)
        values = tuple(sorted(set(self.spec.state.values())))
        channel = Channel(
            self.spec.players,
            self.spec.channel.budget_per_round,
            self.spec.channel.corruption,
            rng,
            values,
        )
        transcript: list[dict[str, Any]] = []
        commits: dict[str, dict[str, Any]] = {}
        leaks = 0
        checked_turns = 0
        bad_receiver_events: list[dict[str, Any]] = []

        for round_no in range(1, self.spec.rounds + 1):
            channel.new_round()
            for order, player in enumerate(self.spec.turn()):
                agent = self.agents[player]
                agent.set_inbox(channel.take_inbox(player))
                agent.merge_inbox(round_no)
                action, rejection = agent.act_on(round_no, transcript)

                # structural view-isolation invariant, re-checked every turn
                view = agent.perceive()
                allowed = self.spec.views[player]
                if any(f not in allowed for f in view):
                    leaks += 1
                checked_turns += 1

                entry: dict[str, Any] = {"round": round_no, "actor": player, "action": _serialize_action(action)}
                if rejection is not None:
                    entry["rejection"] = {"action": rejection.action, "reason": rejection.reason}

                if isinstance(action, Say):
                    if action.receiver != "shared" and action.receiver not in self.spec.players:
                        bad_receiver_events.append({"round": round_no, "actor": player, "receiver": action.receiver})
                        entry["delivered"] = False
                        entry["error"] = f"unknown receiver {action.receiver!r} (shared or a player id required)"
                    else:
                        entry["delivered"] = channel.deliver(round_no, player, action.receiver, action.deltas)
                elif isinstance(action, Reveal):
                    deltas = tuple(
                        fact_delta_for("reveal", player, fid, self.spec.state[fid], round_no, order, self.spec.name)
                        for fid in action.fact_ids
                    )
                    entry["delivered"] = channel.deliver(round_no, player, "shared", deltas)
                elif isinstance(action, Commit):
                    commits[player] = dict(action.payload)

                if channel.events:
                    new = channel.events[len(entry.get("events", [])) :]
                    if new:
                        entry["events"] = [e.__dict__ for e in channel.events]
                transcript.append(entry)

        # strip the cumulative per-entry event lists (kept once, in aggregate)
        for e in transcript:
            e.pop("events", None)

        scores = self._make_scored() if False else self._make_scorer()(commits, self)

        audit = {p: tom_audit(self.agents[p], self.spec).to_dict() for p in self.spec.players}

        report: dict[str, Any] = {
            "game": self.spec.name,
            "seed": self.seed,
            "rounds": self.spec.rounds,
            "players": list(self.spec.players),
            "channel": {
                "budget_per_round": self.spec.channel.budget_per_round,
                "corruption_probability": self.spec.channel.corruption,
                "sent_totals": channel.sent_totals(),
                "events": [e.__dict__ for e in channel.events],
                "bad_receivers": bad_receiver_events,
            },
            "agents": {
                p: {
                    "capabilities": sorted(a.capabilities),
                    "policy_note": a.policy_note,
                    "rejections": [r.__dict__ for r in a.rejections],
                    "observe_reports": a.observe_reports,
                    "codex_assertions": len(a.codex.query()),
                }
                for p, a in self.agents.items()
            },
            "commits": commits,
            "scores": scores,
            "audit": audit,
            "negative_control": {"view_leaks": leaks, "checked_turns": checked_turns},
        }
        canonical = json.dumps(report, indent=2, sort_keys=True, ensure_ascii=False)
        report["determinism_hash"] = "sha256:" + hashlib.sha256(canonical.encode("utf-8")).hexdigest()
        report["transcript"] = transcript

        if write:
            out = default_out_dir(out_dir)
            (out / "phase-5").mkdir(parents=True, exist_ok=True)
            (out / "phase-5" / f"{self.spec.name}.json").write_text(
                json.dumps(report, indent=2, sort_keys=True, ensure_ascii=False) + "\n", encoding="utf-8"
            )
        return report


def default_out_dir(out_dir: "str | Any") -> "Any":
    """Result root per the results-hygiene rule (KAINOS_RESULTS_DIR)."""

    from pathlib import Path

    from kainos.harness.paths import default_results_dir

    return Path(out_dir) if out_dir is not None else default_results_dir()

"""T1 kernel demos — the loop, proven end to end.

Two 2-player, 4-round scripted games over the shared kernel:

1. ``shared-view`` (the clean sharing case): disjoint private views +
   one shared fact; each agent shares its own cell (round 2), re-shares
   it (round 3 — exercises idempotent re-merge), then COMMITS the other
   agent's cell learned from the transcript (round 4). While learning,
   each stores a first-order belief about what the other said (the
   audited mental model). Expected: both commits correct, zero
   violations, zero view leaks, idempotent duplicates recorded.

2. ``contradiction-talk`` (the dispute probe): same grid, but agent b
   starts from a WRONG prior about a's cell, says it (round 2), learns
   the truth from a's honest share (round 3), and corrects itself
   publicly (round 3). Agent a's store must then hold BOTH the wrong
   and the right claim as a DISPUTED pair — cross-linked, never
   averaged (A5 at the social scale) — and a's audit must show the
   deception recorded (one incorrect belief) with zero violations
   (everything was backed by actual speech).

Both are deterministic (seed 1, fixed policies, no wall clock); the
official run writes ``results/phase-5/<game>.json``.
"""

from __future__ import annotations

from typing import Any, Callable

from kainos.codex.models import EpistemicState
from kainos.codex.memory import InMemoryCodexStore
from kainos.game.agent import Agent, StepFn, belief_assertion, deterministic_id, fact_delta_for
from kainos.game.actions import Commit, Pass, Say
from kainos.game.scheduler import Game
from kainos.game.spec import ChannelSpec, GameSpec

__all__ = ["CONTRADICTION_SPEC", "SHARED_SPEC", "run_demo_games"]

_STATE: dict[str, str] = {
    "s:shared_goal": "clear_the_ford",
    "pa:a_cell": "convoy_route_a",
    "pb:b_cell": "convoy_route_b",
}
_VIEWS: dict[str, frozenset[str]] = {
    "a": frozenset({"s:shared_goal", "pa:a_cell"}),
    "b": frozenset({"s:shared_goal", "pb:b_cell"}),
}
_CHANNEL = ChannelSpec(budget_per_round=2, corruption=0.0)

SHARED_SPEC = GameSpec("shared-view", ("a", "b"), dict(_STATE), dict(_VIEWS), _CHANNEL, rounds=4)

#: b's wrong prior in the contradiction game (the seeded false rumor).
_WRONG_PRIOR = "convoy_route_z"

CONTRADICTION_SPEC = GameSpec("contradiction-talk", ("a", "b"), dict(_STATE), dict(_VIEWS), _CHANNEL, rounds=4)


def _other_speech(agent: Agent, other: str) -> list:
    """Fact assertions in this agent's store that came from the other."""

    out = []
    for x in agent.codex.query():
        if x.subject.id.startswith("fact:") and x.relation.id == "is" and (
            x.provenance is not None and x.provenance.source is not None and x.provenance.source.uri == f"agent:{other}"
        ):
            out.append(x)
    return out


def _store_beliefs(agent: Agent, other: str) -> None:
    """First-order model maintenance: for every fact the other has
    asserted, keep a SUPPORTED belief assertion (self-derived, evidence =
    the received assertion's id). Already-stored beliefs are a no-op
    (deterministic ids)."""

    for x in _other_speech(agent, other):
        fid, _, value = x.object_id.partition("=") if False else (x.subject.id[len("fact:") :], "", x.object_id)
        fid = x.subject.id[len("fact:") :]
        value = x.object_id
        belief = belief_assertion(
            self_id=agent.player_id,
            other=other,
            fact_id=fid,
            value=value,
            source_uri=f"agent:{agent.player_id}",
            evidence=(x.id,),
        )
        try:
            agent.codex.get(belief.id)
        except KeyError:
            agent.remember(belief)


def _learned_value(agent: Agent, other: str, fact_id: str) -> str | None:
    """The value the other agent asserted for a fact (latest speech)."""

    values = [x.object_id for x in _other_speech(agent, other) if x.subject.id == f"fact:{fact_id}"]
    return values[-1] if values else None


def _make_shared_policy(agent_ref: Callable[[], Agent], player: str, other: str, my_fact: str, their_fact: str) -> StepFn:
    game_name = SHARED_SPEC.name

    def step(view: dict[str, str], round_no: int, transcript: list[dict[str, Any]]) -> Any:
        agent = agent_ref()
        _store_beliefs(agent, other)
        if round_no == 1:
            return Pass()
        if round_no in (2, 3):  # share (2) + re-share (3: idempotency check)
            delta = fact_delta_for("say", player, my_fact, view[my_fact], round_no, 0, game_name)
            return Say("shared", (delta,))
        value = _learned_value(agent, other, their_fact)
        if value is None:
            return Pass()  # honestly: cannot commit what one has not learned
        return Commit({"their_cell": value, "their_fact": their_fact})

    return step


def _make_contradiction_policy(
    agent_ref: Callable[[], Agent],
    player: str,
    other: str,
    my_fact: str,
    their_fact: str,
    game_name: str = CONTRADICTION_SPEC.name,
) -> StepFn:
    """b's script (player == 'b'): wrong prior at r2, correction + own
    share at r3, commit at r4. a's script (player == 'a'): honest share
    at r2, pass at r3 (absorbing b's wrong claim), commit at r4."""

    def step(view: dict[str, str], round_no: int, transcript: list[dict[str, Any]]) -> Any:
        agent = agent_ref()
        _store_beliefs(agent, other)
        if round_no == 1:
            return Pass()
        if round_no == 2:
            if player == "b":
                # the seeded false rumor about a's cell (an attributed,
                # checkable claim — the kernel records it, the store
                # preserves its later contradiction)
                delta = fact_delta_for("say", "b", "pa:a_cell", _WRONG_PRIOR, round_no, 0, game_name)
                return Say("shared", (delta,))
            return Say("shared", (fact_delta_for("say", "a", my_fact, view[my_fact], round_no, 0, game_name),))
        if round_no == 3:
            if player == "b":
                truth = _learned_value(agent, "a", "pa:a_cell")
                deltas = []
                if truth is not None and truth != _WRONG_PRIOR:
                    deltas.append(fact_delta_for("say", "b", "pa:a_cell", truth, round_no, 0, game_name))
                deltas.append(fact_delta_for("say", "b", my_fact, view[my_fact], round_no, 1, game_name))
                return Say("shared", tuple(deltas))
            return Pass()
        value = _learned_value(agent, other, their_fact)
        if value is None:
            return Pass()
        return Commit({"their_cell": value, "their_fact": their_fact})

    return step


def _score(commits: dict[str, dict[str, Any]], game: Game) -> dict[str, Any]:
    st = game.spec.state
    a = commits.get("a", {})
    b = commits.get("b", {})
    a_ok = a.get("their_cell") == st["pb:b_cell"] and a.get("their_fact") == "pb:b_cell"
    b_ok = b.get("their_cell") == st["pa:a_cell"] and b.get("their_fact") == "pa:a_cell"
    return {"a_correct": a_ok, "b_correct": b_ok, "score": 1.0 if (a_ok and b_ok) else 0.0}


def _build_shared() -> Game:
    spec = SHARED_SPEC
    holders: dict[str, Agent] = {}

    def mk(player: str, other: str, my_fact: str, their_fact: str) -> Agent:
        step = _make_shared_policy(lambda: holders[player], player, other, my_fact, their_fact)
        a = Agent(player, spec, step)
        holders[player] = a
        return a

    return Game(spec, {"a": mk("a", "b", "pa:a_cell", "pb:b_cell"), "b": mk("b", "a", "pb:b_cell", "pa:a_cell")}, seed=1, scorer=_score)


def _build_contradiction() -> Game:
    spec = CONTRADICTION_SPEC
    holders: dict[str, Agent] = {}

    def mk(player: str, other: str, my_fact: str, their_fact: str) -> Agent:
        step = _make_contradiction_policy(lambda: holders[player], player, other, my_fact, their_fact)
        a = Agent(player, spec, step)
        holders[player] = a
        return a

    return Game(spec, {"a": mk("a", "b", "pa:a_cell", "pb:b_cell"), "b": mk("b", "a", "pb:b_cell", "pa:a_cell")}, seed=1, scorer=_score)


def run_demo_games(out_dir: Any = None) -> dict[str, dict[str, Any]]:
    """Run both kernel demos; write their reports to
    ``<results root>/phase-5/<game>.json`` (results-hygiene rule)."""

    reports: dict[str, dict[str, Any]] = {}
    for game in (_build_shared(), _build_contradiction()):
        reports[game.spec.name] = game.run(write=True, out_dir=out_dir)
    return reports

