        v = views[cid]
        band = BANDS.index(concept(cid).band) if concept(cid).band in BANDS else len(BANDS)
        return (0 if v.state is MasteryState.PRACTICING else (1 if v.state is MasteryState.EXPOSED else 2), band, cid)

