"""Filter a file's diff against HEAD to KEEP-ONLY the genuine
(line-changing) hunks, dropping pure-whitespace reformat hunks, then
apply the filtered patch to the (restored) worktree file."""
import re, subprocess, sys, difflib, io

def norm(line: str) -> str:
    return re.sub(r"\s+", " ", line.strip())

def genuine_lines(old_lines, new_lines):
    # a hunk keeps genuine change if the normalized line multisets differ
    return sorted(map(norm, old_lines)) != sorted(map(norm, new_lines))

def filter_patch(diff_text: str) -> list[str]:
    """Split a unified diff into hunks; drop the pure-format ones."""
    out = []
    lines = diff_text.splitlines(keepends=True)
    header, i = [], 0
    while i < len(lines) and not lines[i].startswith("@@"):
        header.append(lines[i]); i += 1
    hunk = []
    hunks = []
    while i < len(lines):
        if lines[i].startswith("@@"):
            if hunk: hunks.append(hunk)
            hunk = [lines[i]]; i += 1
            oldn = newn = []
            while i < len(lines) and not lines[i].startswith("@@"):
                hunk.append(lines[i])
                l = lines[i]
                if l.startswith("-"): oldn.append(l[1:])
                elif l.startswith("+"): newn.append(l[1:])
                elif l.startswith(" ") or l == "\n": pass
                i += 1
            if genuine_lines(oldn, newn):
                out.extend(hunk)
            else:
                out.append("@@ dropped-format-hunk @@\n")  # placeholder -> removed below
        else:
            i += 1
    if hunk: hunks.append(hunk)
    # rebuild: join header + kept hunks, but @@ placeholders are removed by regex on final text
    return header

def process(path: str):
    diff = subprocess.run(["git", "diff", "-U3", "HEAD", "--", path], capture_output=True, text=True, cwd=".").stdout
    # per-hunk filtering with git apply is fiddly when offsets shift; instead
    # we compute the final content directly: walk the diff, applying kept hunks
    # to the HEAD content.
    head = io.open(path, encoding="utf-8").read().splitlines()
    lines = diff.splitlines()
    # locate hunks
    idxs = [i for i, l in enumerate(lines) if l.startswith("@@")]
    result = []
    pos = 0
    for k in idxs:
        m = re.match(r"@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@", lines[k])
        old_start = int(m.group(1))
        # find matching hunk end
        j = k + 1
        oldn, newn = [], []
        while j < len(lines) and not lines[j].startswith("@@"):
            l = lines[j]
            if l.startswith("-"): oldn.append(l[1:]); 
            elif l.startswith("+"): newn.append(l[1:])
            elif l.startswith(" "): pass
            j += 1
        # content to copy before this hunk
        result.extend(head[pos:old_start - 1])
        if genuine_lines(oldn, newn):
            result.extend(newn)
        else:
            result.extend(oldn)
        pos = old_start - 1 + len(oldn)
    result.extend(head[pos:])
    io.open(path, "w", encoding="utf-8").write("\n".join(result) + "\n")
    kept = 0
    for k in idxs:
        j = k + 1; oldn = newn = []
        while j < len(lines) and not lines[j].startswith("@@"):
            l = lines[j]
            if l.startswith("-"): oldn.append(l[1:])
            elif l.startswith("+"): newn.append(l[1:])
            j += 1
        if genuine_lines(oldn, newn): kept += 1
    print(f"{path}: hunks total={len(idxs)} kept={kept}")

