def _j_py(n0: int) -> int:
    def _is_prime(m0: int) -> bool:
        d0 = 2
        while d0 * d0 <= m0:
            if m0 % d0 == 0:
                return False
            d0 += 1
        return m0 >= 2

    total = 0
    for p0 in range(2, n0 + 1):
        if not _is_prime(p0):
            continue
        pk = p0
        while pk <= n0:
            total += (pk // p0) * (p0 - 1)
            pk *= p0
    return total

