    res = _checks(runs, report, out_dir)
    report["checks"] = res["checks"]
    report["passed"] = res["passed"]
    report["value"] = res["value"]
    for name in ("e6.12-run1", "e6.12-run2"):
        (out_dir / name / "e6.12-report.json").write_text(
