            return {"error": f"the official e6.13 seed store is missing: {seed}"}
        (root / "codeX-S01.json").write_bytes(seed.read_bytes())  # the seed
        runs[name] = _run_once(root)
    from kainos.tutor.bands import BAND_MAP, validate_band_map

