"""The reference registry (bandgen v0.1).

Beds are DECLARED as computations, never as hand-written values:
the spec names a reference function + args, and bandgen evaluates it
against the SAME python reference the experiments' P4 checks import
(brainstem's ``_s13_py_*`` / ``_s11_py_*`` family). One reference
implementation serves both the compiler and the referee — the
D-e6h(b) hand-computed-bed bug class cannot exist in a value that is
computed, not written.

The registry is open by design: each band adds its own reference
functions here (or in its brainstem module and registers them) as
the curriculum grows. v0.1 ships the S11/S12/S13 (fundamentals)
references needed to reproduce the S13 acceptance case.
"""

from __future__ import annotations

from fractions import Fraction
from typing import Any, Callable

from kainos.tutor import brainstem as B


def _frac_words(v: Fraction) -> str:
    """The house word rendering (exactly the experiments' ``_frac``:
    '85 over 168'; integers render bare)."""
    return f"{v.numerator} over {v.denominator}" if v.denominator != 1 else str(v.numerator)


def _frac_slash(v: Fraction) -> str:
    return f"{v.numerator}/{v.denominator}"


# --- S13 (the zeta variants) references --------------------------------

def ref_family(sign: int, indexset: str, exp: int, N: int = 84) -> Fraction:
    """A family partial: sign ±, index set all/primes/composites,
    exponent s, height N (the store's own python reference)."""
    return B._s13_py_family(sign, indexset, exp, N)


def ref_telescope(N: int) -> Fraction:
    """The telescope spot (N+1)/(2N) as an exact rational."""
    return B._s13_py_telescope(N)


def ref_removal(p: int, exp: int) -> Fraction:
    """The single-prime removal multiplier p^s / (p^s - 1)."""
    return B._s13_py_removal(p, exp)


def ref_removal_max(exp: int, N: int = 84) -> tuple[int, str]:
    """The largest removal multiplier on the line at s=exp, with the
    prime it stands at (the S13_BEDS 'removal_max_s2/s3' shape:
    (prime, word))."""
    best_p, best_v = 0, Fraction(0)
    for p in B._s13_py_primes(N):
        v = B._s13_py_removal(p, exp)
        if v > best_v:
            best_p, best_v = p, v
    return (best_p, _frac_words(best_v))


def ref_set_removal(primes: list[int], exp: int) -> Fraction:
    """The set-removal multiplier: the product of the single removals
    over the named primes (removing several terms multiplies by the
    product of their reciprocals' reciprocals — control: the bed
    cross-check catches a reciprocal product, D-e6h(b))."""
    acc = Fraction(1)
    for p in primes:
        acc *= B._s13_py_removal(p, exp)
    return acc


def ref_census(end: int = 84) -> dict[str, int]:
    """The line census above one: integers / primes / composites
    (the S13_BEDS 'census' shape)."""
    ps = B._s13_py_primes(end)
    integers = end - 1
    return {"integers": integers, "primes": len(ps), "composites": integers - len(ps)}


def ref_removal_below2_count(exp: int, N: int = 84) -> int:
    """How many single-removal multipliers on the line stay below 2
    (every one of them does at s=2 — the S13_BEDS count shape)."""
    return sum(1 for p in B._s13_py_primes(N) if B._s13_py_removal(p, exp) < 2)


def ref_telescope_spots(heights: list[int]) -> dict[str, str]:
    """The named telescope spots as {str(N): 'a/b'} (slash rendering,
    the S13_BEDS 'telescope_spots' shape)."""
    return {str(N): _frac_slash(B._s13_py_telescope(N)) for N in heights}


def ref_telescope_named(heights: list[int]) -> tuple[str, ...]:
    """The named-spot values in the given order (the S13_BEDS
    'telescope_named_spots' tuple shape)."""
    return tuple(_frac_slash(B._s13_py_telescope(N)) for N in heights)


def ref_spf_chain(n: int) -> list[int]:
    """The smallest-prime-factor chain (the S11 reference)."""
    return B._s11_py_chain(n)


def ref_spf(n: int) -> int:
    return B._s11_py_spf(n)


def ref_order_s2() -> list[str]:
    """The frozen s=2 ordering of the six family partials (declared
    content, but it is the order the mechanism's own values sort to —
    kept as a reference so the compiler can re-verify it)."""
    vals = {
        "minus-all": B._s13_py_family(-1, "all", 2),
        "minus-prime": B._s13_py_family(-1, "primes", 2),
        "minus-comp": B._s13_py_family(-1, "composites", 2),
        "plus-comp": B._s13_py_family(1, "composites", 2),
        "plus-prime": B._s13_py_family(1, "primes", 2),
        "plus-all": B._s13_py_family(1, "all", 2),
    }
    return [k for k, _ in sorted(vals.items(), key=lambda kv: kv[1])]


#: The registry: spec reference names -> callables. Argument names in
#: the spec's "args" object map to the callable's parameters.
REGISTRY: dict[str, Callable[..., Any]] = {
    "family": ref_family,
    "telescope": ref_telescope,
    "removal": ref_removal,
    "removal_max": ref_removal_max,
    "set_removal": ref_set_removal,
    "census": ref_census,
    "removal_below2_count": ref_removal_below2_count,
    "telescope_spots": ref_telescope_spots,
    "telescope_named": ref_telescope_named,
    "spf": ref_spf,
    "spf_chain": ref_spf_chain,
    "order_s2": ref_order_s2,
}

#: Fraction renderers for the beds table.
RENDERERS: dict[str, Callable[[Any], Any]] = {
    "slash": _frac_slash,
    "frac_words": _frac_words,
    "json": lambda v: v,
}


def evaluate(ref_name: str, args: dict[str, Any]) -> Any:
    if ref_name not in REGISTRY:
        raise KeyError(f"unknown bed reference {ref_name!r} (registry: {sorted(REGISTRY)})")
    return REGISTRY[ref_name](**args)

"""Spec loading + validation (bandgen).

Two layers:
1. JSON-schema validation (specs/band_spec.schema.json) — the shape.
2. Structural checks — the curriculum's own logic: prereq graphs
   point down and stay acyclic, theorem part sets are subsets of the
   band's taught lessons (scaffolds are STRICT subsets), turn refs
   are unique and padded, wall articulations name the line end, and
   the denied corpus scan (the carried S9_DENYLIST) is clean over
   every question and every declared byte.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import jsonschema

from kainos.tutor.brainstem import S9_DENYLIST

REPO_ROOT = Path(__file__).resolve().parents[2]
SCHEMA_PATH = REPO_ROOT / "specs" / "band_spec.schema.json"


def load_spec(path: str | Path) -> dict[str, Any]:
    p = Path(path)
    if not p.is_absolute():
        p = REPO_ROOT / p
    doc = json.loads(p.read_text(encoding="utf-8"))
    schema = json.loads(SCHEMA_PATH.read_text(encoding="utf-8"))
    jsonschema.validate(doc, schema)
    return doc


def structural_checks(spec: dict[str, Any]) -> list[str]:
    """The curriculum-logic checks; returns a list of problem strings
    (empty = clean)."""
    bad: list[str] = []
    band = spec["band"]

    # Concept ids vs the new_concepts list.
    concept_ids = [c["id"] for c in band["concepts"]]
    if concept_ids != band["new_concepts"]:
        bad.append(f"new_concepts {band['new_concepts']} != concepts order {concept_ids}")

    # Prereqs point DOWN: an earlier concept of this band, or a seed
    # concept (the seed-side existence is verified by the dry-run
    # against the booted registry; here we only check acyclicity and
    # in-band ordering — prereqs must appear EARLIER in the list).
    seen: set[str] = set()
    for c in band["concepts"]:
        for p in c["prereqs"]:
            if p in set(concept_ids) and p not in seen:
                bad.append(f"prereq cycle/forward-ref: {c['id']} <- {p}")
        seen.add(c["id"])

    # Lesson slugs and theorem parts.
    lesson_slugs = {c["lesson"]["slug"] for c in band["concepts"]}
    for t in band["theorems"]:
        if t["concept"] not in concept_ids:
            bad.append(f"theorem {t['id']} owns unknown concept {t['concept']!r}")
        for part in t["parts"]:
            if part not in lesson_slugs:
                bad.append(f"theorem {t['id']} part {part!r} is not a taught lesson of the band")

    # new_fact_ids: lessons first, then theorems, exact set.
    want_facts = [f"lemma:{s}" for c in band["concepts"] for s in [c["lesson"]["slug"]]]
    want_facts += [f"theorem:{t['id']}" for t in band["theorems"]]
    if band["new_fact_ids"] != want_facts:
        bad.append(f"new_fact_ids {band['new_fact_ids']} != lesson-then-theorem order {want_facts}")

    # Turns: refs unique, padded, consistent with sessions, ordered.
    refs: list[str] = []
    per_session: dict[str, int] = {}
    for i, t in enumerate(spec["turns"]):
        r = t["ref"]
        if r in refs:
            bad.append(f"duplicate turn ref {r}")
        refs.append(r)
        sess = int(r[1:3])
        if sess not in spec["sessions"]:
            bad.append(f"turn {r} session {sess} not in sessions {spec['sessions']}")
        per_session[sess] = per_session.get(sess, 0) + 1
    for sess in spec["sessions"]:
        if len([r for r in refs if int(r[1:3]) == sess]) != per_session.get(sess, 0):
            bad.append(f"session {sess} turn count mismatch")
    expected = []
    for sess in spec["sessions"]:
        n = per_session.get(sess, 0)
        expected += [f"S{sess:02d}:{j:02d}" for j in range(1, n + 1)]
    if refs != expected:
        bad.append("turn refs are not the contiguous padded sequences of their sessions")

    # Kind-specific requirements.
    for t in spec["turns"]:
        k = t["kind"]
        if k == "gap" and not (t.get("concept") and t.get("fragment")):
            bad.append(f"{t['ref']}: gap needs concept + fragment")
        if k == "teach" and not t.get("lesson"):
            bad.append(f"{t['ref']}: teach needs lesson")
        if k == "derive":
            if not (t.get("theorem") and t.get("parts")):
                bad.append(f"{t['ref']}: derive needs theorem + parts")
            else:
                th = next((x for x in band["theorems"] if x["id"] == t["theorem"]), None)
                if th is None:
                    bad.append(f"{t['ref']}: derive unknown theorem {t['theorem']!r}")
                elif sorted(t["parts"]) != sorted(th["parts"]):
                    bad.append(f"{t['ref']}: derive parts {t['parts']} != sanctioned {th['parts']}")
        if k == "scaffold" and not (t.get("theorem") and t.get("parts") and t.get("expected")):
            bad.append(f"{t['ref']}: scaffold needs theorem + parts + expected")
        if k == "scaffold" and t.get("parts"):
            th = next((x for x in band["theorems"] if x["id"] == t.get("theorem")), None)
            if th and sorted(t["parts"]) == sorted(th["parts"]):
                bad.append(f"{t['ref']}: scaffold parts must be a PROPER subset of the sanctioned set")
        if k == "missing_parts" and not (t.get("expected") and t.get("theorem")):
            bad.append(f"{t['ref']}: missing_parts needs expected + theorem")
        if k == "wall":
            w = t.get("wall") or {}
            if not w.get("text", "").startswith("needs_info: "):
                bad.append(f"{t['ref']}: wall text must start with 'needs_info: '")
            artic = w.get("articulation", [])
            if not any("line end" in a for a in artic):
                bad.append(f"{t['ref']}: every wall articulation must name the line end")
        if k == "carry" and not (t.get("source") or {}).get("band"):
            bad.append(f"{t['ref']}: carry needs source.band")
        bed = t.get("bed")
        if bed:
            if bed["expect"] == "literal" and "value" not in bed:
                bad.append(f"{t['ref']}: literal bed needs value")
            if bed["expect"] == "frac" and not bed.get("ref"):
                bad.append(f"{t['ref']}: frac bed needs a reference")

    # Beds table: refs resolvable.
    from .reflib import REGISTRY

    for b in spec.get("beds", []):
        if "ref" in b and b["ref"] not in REGISTRY:
            bad.append(f"beds[{b['key']}]: unknown reference {b['ref']!r}")

    # Denylist: the carried S9 corpus scan over the script + every
    # declared byte (questions, wall texts, lesson statements, theorem
    # statements, and the declared expected bytes).
    corpus: list[tuple[str, str]] = []
    for t in spec["turns"]:
        corpus.append((f"script:{t['ref']}", t["question"]))
        w = t.get("wall") or {}
        if w.get("text"):
            corpus.append((f"wall:{t['ref']}", w["text"]))
        if t.get("expected"):
            corpus.append((f"expected:{t['ref']}", t["expected"]))
    for c in band["concepts"]:
        corpus.append(("lesson:" + c["lesson"]["slug"], c["lesson"]["statement"]))
    for t in band["theorems"]:
        corpus.append(("theorem:" + t["id"], t["statement"]))
    deny = set(S9_DENYLIST)
    for where, text in corpus:
        for wd in sorted(deny):
            if wd and wd in text:
                bad.append(f"denylist hit: {wd!r} in {where}: {text[:60]}...")

    return bad

"""The control (bandgen v0.1): dry-run the spec, capture the
mechanism's own output, build the frozen-shape table, and report the
diff between the spec's declarations/predictions and the mechanism.

The compiler never edits the mechanism: it drives the runtime exactly
as the experiments do (boot/turn/lapse), captures the session dumps,
and reports. The D-e6z deviation classes (hand letters, hand counts,
hand beds, hand carries, hand pre-states) all surface here as
prediction-vs-mechanism diffs on a clean, reviewable report — at SPEC
time, not at build time.
"""

from __future__ import annotations

import json
from fractions import Fraction
from pathlib import Path
from typing import Any

from kainos.tutor import brainstem as B
from kainos.tutor.session import load_store

from . import reflib, storeio
from .spec import REPO_ROOT, structural_checks


def turn_letter(t: dict[str, Any]) -> str:
    """The e614 letter mapping — the house's canonical domain letters
    (L lesson teach, U impossible/gap, F part-set failure, T
    derive-success, C conditional, H honest wall, S derived). Mirrors
    the experiments' ``_turn_domain`` exactly."""
    if t["kind"] == "assertion" and (t["slots"] or {}).get("lemma"):
        return "L"
    if t["kind"] == "impossible":
        return "U"
    ir = t["response_ir"] or {}
    mode = (t["slots"] or {}).get("mode")
    if mode == "derive":
        return "T" if ir.get("uncertainty_state") == "derived" else "F"
    if ir.get("uncertainty_state") == "needs_info":
        return "H"
    if ir.get("uncertainty_state") == "conditional":
        return "C"
    return "S"


def turn_answer(t: dict[str, Any]) -> str | None:
    return (t.get("response_ir") or {}).get("answer")


def _seeded_registry(spec: dict[str, Any]) -> tuple:
    name = spec.get("registry")
    if not name:
        raise ValueError("spec.registry is required (the brainstem concepts tuple for the dry-run)")
    reg = getattr(B, name)
    ids = [c.id for c in reg]
    for c in spec["band"]["concepts"]:
        if c["id"] not in ids:
            raise ValueError(
                f"band concept {c['id']!r} is not in the booted registry {name} — "
                "the brainstem module for this band must be merged before the dry-run"
            )
    return reg


SPECIAL_KINDS = {"wall", "zero_derive", "zero_touch", "unclassified", "gap", "teach", "scaffold", "missing_parts", "carry"}


def run_control(spec: dict[str, Any], workdir: str | Path | None = None) -> dict[str, Any]:
    """Run the full control; returns the report:
    {ok, spec, checks: {name: {pass, bad[]}}, table: <frozen shape>,
    computed_beds, carry_map}."""
    checks: dict[str, dict[str, Any]] = {}
    bad: list[str] = []

    # C0 — structural (schema was validated at load; this is the
    # curriculum-logic layer).
    bad = structural_checks(spec)
    checks["c0_structural"] = {"pass": not bad, "bad": bad}
    if bad:
        return {"ok": False, "spec": spec["id"], "checks": checks, "table": {}, "computed_beds": {}, "carry_map": {}}

    registry = _seeded_registry(spec)
    seed_path = REPO_ROOT / spec["seed"]["store"]
    sessions = spec["sessions"]
    script: dict[int, list[str]] = {s: [] for s in sessions}
    turns = spec["turns"]
    by_ref: dict[str, dict[str, Any]] = {}
    for t in turns:
        script[int(t["ref"][1:3])].append(t["question"])
        by_ref[t["ref"]] = t

    # C1 — the seed (identity / total / line end, computed).
    seed = load_store(seed_path)
    c1: list[str] = []
    ident = storeio.store_identity(seed)
    total = len(seed.query())
    lend = storeio.line_end(seed)
    if ident != spec["seed"]["identity"]:
        c1.append(f"seed identity {ident} != declared {spec['seed']['identity']}")
    if total != spec["seed"]["total"]:
        c1.append(f"seed total {total} != declared {spec['seed']['total']}")
    if lend != spec["seed"]["line_end"]:
        c1.append(f"seed line end {lend} != declared {spec['seed']['line_end']}")
    checks["c1_seed"] = {"pass": not c1, "bad": c1, "identity": ident, "total": total, "line_end": lend}

    # C2 — the computed beds against the reference registry.
    c2: list[str] = []
    computed_beds: dict[str, Any] = {}
    for b in spec.get("beds", []):
        try:
            val = reflib.evaluate(b["ref"], b.get("args", {})) if "ref" in b else b["value"]
            render = b.get("render", "json")
            computed_beds[b["key"]] = (
                reflib.RENDERERS[render](val) if "ref" in b else val
            )
        except Exception as e:
            c2.append(f"bed {b['key']}: {e!r}")
    checks["c2_beds"] = {"pass": not c2, "bad": c2}

    # C3 — the dry-runs (main x2 for the determinism twin + carry).
    work = Path(workdir) if workdir else REPO_ROOT / ".bandgen-scratch" / spec["id"]
    run1_root, run2_root, carry_root = work / "run1", work / "run2", work / "carry"
    for r in (run1_root, run2_root, carry_root):
        storeio.place_seed(seed_path, r)
    dump1 = storeio.run_main(run1_root, sessions, list(registry), script)
    dump2 = storeio.run_main(run2_root, sessions, list(registry), script)
    carry_surfaces = [t["question"] for t in turns if t["kind"] == "carry"]
    carry_surfaces += [o["question"] for o in spec.get("offscript", [])]
    carry_runs = storeio.run_carry(carry_root, list(registry), carry_surfaces) if carry_surfaces else []

    # Collect per-ref captured turns.
    captured: dict[str, dict[str, Any]] = {}
    for s in sessions:
        row = next(x for x in dump1 if x["session"] == s)
        ts = row["turns"]
        for j, t in enumerate(ts, start=1):
            captured[f"S{s:02d}:{j:02d}"] = t
    if len(captured) != len(turns):
        checks["c3_capture"] = {"pass": False, "bad": [f"captured {len(captured)} turns != {len(turns)} declared"]}
        return {"ok": False, "spec": spec["id"], "checks": checks, "table": {}, "computed_beds": computed_beds, "carry_map": {}}

    final = storeio.fresh_final(run1_root, max(sessions))
    seed_ids = {a.id for a in seed.query()}
    final_ids = {a.id for a in final.query()}

    # C4 — the letters (the e614 mapping over the captured turns).
    c4: list[str] = []
    letters: dict[str, str] = {}
    for s in sessions:
        letters[str(s)] = "".join(turn_letter(t) for t in captured[f"S{s:02d}:{j:02d}"].values() if False or True) if False else "".join(
            turn_letter(captured[f"S{s:02d}:{j:02d}"]) for j in range(1, len(script[s])) + 1
        )
        want = spec["expect"]["letters"].get(str(s), "")
        if want and want != letters[str(s)]:
            c4.append(f"session {s}: predicted letters {want!r} != mechanism {letters[str(s)]!r}")
    checks["c4_letters"] = {"pass": not c4, "bad": c4, "letters": letters}

    # C5 — per-kind semantic checks (the spec declarations vs the
    # captured mechanism bytes).
    c5: list[str] = []
    gaps: dict[str, str] = {}
    teach: dict[str, str] = {}
    scf: dict[str, str] = {}
    mpf: dict[str, str] = {}
    dvs: dict[str, Any] = {}
    walls: dict[str, str] = {}
    wall_art: dict[str, list[str]] = {}
    beds_exact: dict[str, str] = {}
    bed_grounded: dict[str, list[str]] = {}
    bed_owners: dict[str, str] = {}
    thm_allowed: dict[str, list[str]] = {}
    derived: dict[str, str] = {}
    zero_derive_text = ""
    zero_touch_text = ""
    unclassified_text = ""
    carry_refs: list[str] = []
    thm_statements = {t["id"]: t["statement"] for t in spec["band"]["theorems"]}

    for ref in sorted(by_ref):
        t = by_ref[ref]
        cap = captured[ref]
        kind = t["kind"]
        ans = turn_answer(cap)
        if kind == "gap":
            gap = (cap["response_ir"] or {}).get("gap") or ""
            if not gap.endswith(t["fragment"]):
                c5.append(f"{ref}: gap byte {gap!r} does not name the declared fragment {t['fragment']!r}")
            gaps[ref] = t["fragment"]
        elif kind == "teach":
            fid = f"lemma:{t['lesson']}"
            if fid not in final_ids:
                c5.append(f"{ref}: taught lesson {fid} is not in the final store")
            elif turn_letter(cap) != "L":
                c5.append(f"{ref}: teach turn did not take the lesson slot (letter {turn_letter(cap)})")
            teach[ref] = fid
        elif kind == "derive":
            if turn_letter(cap) != "T":
                c5.append(f"{ref}: derive turn letter {turn_letter(cap)} != T")
            fid = f"theorem:{t['theorem']}"
            if fid not in final_ids:
                c5.append(f"{ref}: derived theorem {fid} is not in the final store")
            dvs[ref] = [t["theorem"], list(t["parts"])]
        elif kind == "scaffold":
            if ans != t["expected"]:
                c5.append(f"{ref}: scaffold byte {ans!r} != declared {t['expected'][:60]!r}...")
            scf[ref] = ans or ""
        elif kind == "missing_parts":
            if ans != t["expected"]:
                c5.append(f"{ref}: missing-parts byte {ans!r} != declared")
            mpf[ref] = ans or ""
        elif kind == "wall":
            w = t["wall"]
            if ans != w["text"]:
                c5.append(f"{ref}: wall byte drift: {ans!r} != declared {w['text'][:60]!r}...")
            for frag in w["articulation"]:
                if frag not in (ans or ""):
                    c5.append(f"{ref}: wall articulation fragment missing: {frag!r}")
            walls[ref] = ans or ""
            wall_art[ref] = list(w["articulation"])
        elif kind == "zero_derive":
            if ans != t["expected"]:
                c5.append(f"{ref}: zero-derive byte drift")
            zero_derive_text = ans or ""
        elif kind == "zero_touch":
            if ans != t["expected"]:
                c5.append(f"{ref}: zero-touch byte drift")
            zero_touch_text = ans or ""
        elif kind == "unclassified":
            if ans != t["expected"]:
                c5.append(f"{ref}: unclassified byte drift")
            unclassified_text = ans or ""
        elif kind == "carry":
            carry_refs.append(ref)
        bed = t.get("bed")
        if bed:
            if bed["expect"] == "literal":
                if ans != bed["value"]:
                    c5.append(f"{ref}: bed byte {ans!r} != declared literal {bed['value'][:60]!r}...")
            else:
                val = reflib.evaluate(bed["ref"], bed.get("args", {}))
                tmpl = bed.get("template", "{v}")
                want = tmpl.format(v=reflib.RENDERERS["frac_words"](val) if isinstance(val, Fraction) else val)
                if ans != want:
                    c5.append(f"{ref}: bed byte {ans!r} != reference rendering {want[:60]!r}...")
            beds_exact[ref] = ans or ""
            bed_grounded[ref] = list(bed["grounds"])
            bed_owners[ref] = bed["owner"]
            for g in bed["grounds"]:
                if g not in final_ids:
                    c5.append(f"{ref}: bed ground {g!r} is not in the final store")
        if t.get("cite"):
            thm_allowed[ref] = list(t["cite"])
            for c in t["cite"]:
                st = thm_statements.get(c)
                if st is not None and st not in (ans or ""):
                    c5.append(f"{ref}: cited theorem statement {c!r} not present in the answer")
        if kind not in SPECIAL_KINDS:
            if ans is None:
                c5.append(f"{ref}: expected a derived answer, got none (gap: {(cap['response_ir'] or {}).get('gap')!r})")
            else:
                derived[ref] = ans

    checks["c5_kinds"] = {"pass": not c5, "bad": c5}

    # C6 — the seam carries (the seed-only runtime must re-answer
    # byte-identically; the P6 mechanic).
    c6: list[str] = []
    offscript_carry: dict[str, Any] = {}
    carry_answers = {o["question"]: o for o in spec.get("offscript", [])}
    for i, rec in enumerate(carry_runs):
        ir = rec.response_ir or {}
        surf = carry_surfaces[i]
        if surf in carry_answers:
            want = offscript_carry  # off-script (not part of the labeled script)
            offscript_carry[surf] = ir.get("answer")
            o = carry_answers[surf]
            if o.get("expect_derived", True) and ir.get("uncertainty_state") != "derived":
                c6.append(f"off-script {surf!r}: not a grounded derivation")
        else:
            ref = next(r for r, t in by_ref.items() if t["kind"] == "carry" and t["question"] == surf)
            main_ans = turn_answer(captured[ref])
            if ir.get("answer") != main_ans:
                c6.append(f"{ref}: seed-only carry drifted ({ir.get('answer')!r} != S-run {main_ans!r})")
    checks["c6_carry"] = {"pass": not c6, "bad": c6, "seam_carry_refs": sorted(carry_refs)}

    # C7 — mastery (pre-states computed from the seed; post from the
    # final store; no regressions; the new concepts at their declared
    # band-end values; the drill census the D-e6y family).
    c7: list[str] = []
    pre = storeio.pre_states(seed_path, registry)
    post = storeio.mastery_snapshot(final, registry)
    drilled: dict[str, int] = {}
    for cid in sorted(pre):
        if cid not in post:
            c7.append(f"carried concept {cid} left the mastery view")
            continue
        if post[cid]["state"] != pre[cid]["state"]:
            c7.append(f"{cid}: pre-state CHANGED ({post[cid]['state']} != {pre[cid]['state']}) (no regressions)")
        delta = post[cid]["correct"] - pre[cid]["correct"]
        if delta < 0:
            c7.append(f"{cid}: correct-derivation count REGRESSED ({post[cid]['correct']} < {pre[cid]['correct']})")
        if delta > 0:
            drilled[cid] = delta
    new_ids = spec["band"]["new_concepts"]
    for cid in new_ids:
        e = spec["expect"].get("mastery", {}).get(cid)
        if e is None:
            c7.append(f"new concept {cid} has no mastery expectation")
            continue
        v = post.get(cid)
        if v is None:
            c7.append(f"new concept {cid} not in the post mastery view")
            continue
        if v["state"] != e["state"] or v["correct"] != e["correct"]:
            c7.append(f"{cid}: post state {v} != declared {e}")
        want_gaps = spec["expect"].get("prereq_gaps", {}).get(cid, [])
        if tuple(v["prereq_gaps"]) != tuple(want_gaps):
            c7.append(f"{cid}: prereq gaps {v['prereq_gaps']} != declared {want_gaps}")
    checks["c7_mastery"] = {"pass": not c7, "bad": c7, "pre_states": len(pre), "drilled": drilled}

    # C8 — the store totals (P8 family: delta accounting, line census,
    # new facts present, the determinism twin).
    c8: list[str] = []
    final_total = len(final_ids)
    new_facts = len(spec["band"]["new_fact_ids"])
    new_events = final_total - spec["seed"]["total"] - new_facts
    if final_total != spec["expect"]["final_total"]:
        c8.append(f"final total {final_total} != declared {spec['expect']['final_total']}")
    if new_events != len(turns):
        c8.append(f"new events {new_events} != {len(turns)} turns (the D-e6y accounting should hold 1:1 at full upsert silence)")
    for fid in spec["band"]["new_fact_ids"]:
        if fid not in final_ids:
            c8.append(f"new fact {fid} is not in the final store")
    if storeio.line_end(final) != spec["seed"]["line_end"]:
        c8.append("the line end moved (a census wrote off-line)")
    succ = storeio.successor_objects(final)
    if succ != set(range(1, spec["seed"]["line_end"] + 1)):
        c8.append("the successor objects are not exactly 1..end")
    twin = dump1 == dump2 and storeio.store_identity(storeio.fresh_final(run2_root, max(sessions))) == storeio.store_identity(final)
    if not twin:
        c8.append("the determinism twin failed")
    checks["c8_totals"] = {"pass": not c8, "bad": c8, "final_total": final_total, "new_facts": new_facts, "new_events": new_events, "twin": twin}

    # C9 — the unconditional/conditional discipline (P0 family): the
    # marker ABSENT on band facts when the band is unconditional,
    # PRESENT on the kept marker facts; and the off-line hygiene:
    # declared off-line witness values must not float up into the
    # on-line derived answers.
    c9: list[str] = []
    marker = "under the condition of the Riemann hypothesis"
    band = spec["band"]
    if band.get("unconditional"):
        for fid in band["new_fact_ids"]:
            try:
                f = final.get(fid)
            except KeyError:
                c9.append(f"P0: {fid} missing")
                continue
            obj = f.object if isinstance(f.object, str) else str(f.object)
            if marker in obj:
                c9.append(f"P0: {fid} carries the condition marker (the band is declared unconditional)")
    for fid in band.get("marker_kept_facts", []):
        try:
            f = final.get(fid)
        except KeyError:
            c9.append(f"P0: carried fact {fid} is not in the final store")
            continue
        obj = f.object if isinstance(f.object, str) else str(f.object)
        if not (marker in obj or "under the condition that" in obj):
            c9.append(f"P0: {fid} lost the condition marker (drift)")
    # Off-line hygiene: the bed table's off-line values (declared
    # literals) must not appear in on-line derived answers.
    offline_literals: set[str] = set()
    for b in spec.get("beds", []):
        if "value" in b and "ref" not in b:
            for v in (b["value"].values() if isinstance(b["value"], dict) else [b["value"]]):
                for piece in (v if isinstance(v, (list, tuple)) else [v]):
                    if isinstance(piece, (int, float)) and not isinstance(piece, bool):
                        offline_literals.add(str(piece))
    for lit in offline_literals:
        for ref, ans in derived.items():
            if lit in ans:
                c9.append(f"off-line literal {lit} leaked into on-line answer at {ref} (the D-e6z hygiene)")
    checks["c9_discipline"] = {"pass": not c9, "bad": c9}

    # The frozen-shape table (the FROZEN dict of the band, rebuildable
    # from the spec + the mechanism).
    table: dict[str, Any] = {
        "seed": spec["seed"]["store"],
        "seed_identity": spec["seed"]["identity"],
        "seed_total": spec["seed"]["total"],
        "line_end_final": spec["seed"]["line_end"],
        "total_turns": len(turns),
        "script": {str(s): list(script[s]) for s in sessions},
        "domain_sequence": letters,
        "derived_table": derived,
        "beds_exact": beds_exact,
        "bed_grounded": bed_grounded,
        "bed_owners": bed_owners,
        "pre_teach_gaps": gaps,
        "teach_turns": teach,
        "scaffold_failures": scf,
        "missing_parts_failure": mpf,
        "derive_successes": dvs,
        "rederive": None,
        "walls_honest": walls,
        "wall_articulations": wall_art,
        "rh_zero_text": zero_derive_text,
        "rh_touch_wall": zero_touch_text,
        "unclassified_honest": {"expected": unclassified_text},
        "seam_carry_refs": sorted(carry_refs),
        "offscript_carry": offscript_carry,
        "seam_crosscheck": spec["expect"].get("seam", {}),
        f"pre_{int(spec['session'][1:])}_{spec['session'].lower()[1:]}_states": pre,
        f"pre_{int(spec['session'][1:])}_{spec['session'].lower()[1:]}_drilled": drilled,
        "mastery_expected": spec["expect"].get("mastery", {}),
        "expected_prereq_gaps": spec["expect"].get("prereq_gaps", {}),
        "theorem_allowed": thm_allowed,
        "theorem_dag": {
            **{s: list(m["parts"]) for s, m in B.S6_THEOREMS.items()},
            **{s: list(m["parts"]) for s, m in B.S7_THEOREMS.items()},
            **{s: list(m["parts"]) for s, m in B.S8_THEOREMS.items()},
            **{s: list(m["parts"]) for s, m in B.S9_THEOREMS.items()},
            **{s: list(m["parts"]) for s, m in B.S10_THEOREMS.items()},
            **{s: list(m["parts"]) for s, m in B.S11_THEOREMS.items()},
            **{s: list(m["parts"]) for s, m in B.S12_THEOREMS.items()},
            **{s: list(m["parts"]) for s, m in B.S13_THEOREMS.items()},
        },
        "new_fact_ids": spec["band"]["new_fact_ids"],
        "new_facts": new_facts,
        "new_events": new_events,
        "final_total": final_total,
        "total_seam_facts": sum(1 for a in final.query() if a.id.startswith("lemma:") or a.id.startswith("theorem:")),
    }

    ok = all(c["pass"] for c in checks.values())
    return {
        "ok": ok,
        "spec": spec["id"],
        "checks": checks,
        "table": table,
        "computed_beds": computed_beds,
        "post_mastery": {cid: post[cid] for cid in sorted(post)},
    }


def render_markdown(report: dict[str, Any]) -> str:
    """The control report as a reviewable markdown table of
    prediction-vs-mechanism (the artifact a human reads before
    freezing)."""
    lines = [f"# bandgen control — {report['spec']}", "",
             f"**{'CLEAN — ready to freeze' if report['ok'] else 'DIFFS — the mechanism disagrees with the spec'}**", ""]
    for name, c in report["checks"].items():
        mark = "PASS" if c["pass"] else "DIFF"
        lines.append(f"## {name} — {mark}")
        for b in c.get("bad", []):
            lines.append(f"- {b}")
        for k in ("letters", "drilled", "identity", "total", "line_end", "final_total", "new_facts", "new_events", "twin", "pre_states", "seam_carry_refs"):
            if k in c:
                lines.append(f"- {k}: {c[k]}")
        lines.append("")
    tbl = report.get("table", {})
    for k in sorted(tbl):
        lines.append(f"- table.{k}: {len(tbl[k]) if isinstance(tbl[k], (dict, list, str)) else tbl[k]}")
    lines.append("")
    beds = report.get("computed_beds", {})
    if beds:
        lines.append("## computed beds (reference-evaluated)")
        for k, v in beds.items():
            lines.append(f"- {k} = {v!r}")
    return "\n".join(lines) + "\n"


def to_json(report: dict[str, Any]) -> str:
    return json.dumps(report, indent=2, sort_keys=True, default=str) + "\n"

