from fractions import Fraction

LINE_END = 84


def py_primes(n):
    out = []
    for x in range(2, n + 1):
        d = 2
        while d * d <= x:
            if x % d == 0:
                break
            d += 1
        else:
            out.append(x)
    return out


A_CURVE = (0, -1, 0)   # (a3, a, b): y^2 + a3 y = x^3 + a x + b
B_CURVE = (1, -1, 0)


def on_curve(P, a3, a, b):
    if P is None:
        return True
    x, y = P
    return y * y + a3 * y == x ** 3 + a * x + b


def neg(P, a3, a, b):
    assert on_curve(P, a3, a, b)
    if P is None:
        return None
    return (P[0], -P[1] - a3)


def add(P, Q, a3, a, b):
    """Chord/tangent on y^2 + a3 y = x^3 + a x + b (a1 = 0)."""
    assert on_curve(P, a3, a, b) and on_curve(Q, a3, a, b), "off-curve input"
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if x1 == x2 and y1 + y2 + a3 == 0:
        return None
    if P == Q:
        if 2 * y1 + a3 == 0:
            return None
        m = Fraction(3 * x1 * x1 + a, 2 * y1 + a3)
    else:
        m = Fraction(y2 - y1, x2 - x1)
    x3 = m * m - x1 - x2
    y3 = -(y1 + m * (x3 - x1)) - a3
    R = (x3, y3)
    assert on_curve(R, a3, a, b), "add: off-curve result (bug in the law)"
    return R


def mul(k, P, a3, a, b, bound=10 ** 7):
    if k < 0:
        return mul(-k, neg(P, a3, a, b), a3, a, b, bound)
    if k > bound:
        raise ValueError("mulp bound exceeded")
    R, A = None, P
    while k > 0:
        if k & 1:
            R = add(R, A, a3, a, b)
        A = add(A, A, a3, a, b)
        k >>= 1
    return R


def count_fp(p, a3, a, b, p2=None):
    """#E(F_p) of the given integral model (valid at primes of good
    reduction of the model)."""
    n = 1
    inv2 = pow(2, -1, p) if p != 2 else 1
    for x in range(p):
        rhs = (x ** 3 + a * x + b) % p
        # y^2 + a3 y - rhs = 0  (mod p)
        if p == 2:
            c = 0
            for y in range(2):
                if (y * y + a3 * y - rhs) % 2 == 0:
                    c += 1
            n += c
            continue
        disc = (a3 * a3 + 4 * rhs) % p
        l = pow(disc, (p - 1) // 2, p)
        if l == p - 1:
            continue
        n += 2 if l == 1 else 1
    return n


def brute_fp(p, a3, a, b):
    n = 1
    for x in range(p):
        rhs = (x ** 3 + a * x + b) % p
        for y in range(p):
            if (y * y + a3 * y - rhs) % p == 0:
                n += 1
    return n


def hasse_census(a3, a, b, end=LINE_END):
    rows = []
    for p in py_primes(end):
        Np = count_fp(p, a3, a, b)
        ap = p + 1 - Np
        assert ap * ap <= 4 * p, f"Hasse violated at p={p} (a,b,a3)=({a},{b},{a3}): a_p={ap}"
        rows.append((p, Np, ap))
    return rows


def torsion_candidates(curve, bound=200):
    a3, a, b = curve
