    # prime of the line, for both panels, plus the Hasse bound.
    cm_bad: list[str] = []
    apA, apB = _ap_table(*B14_A), _ap_table(*B14_B)
    for p in _PRIMES_:
        aA, aB = apA[str(p)], apB[str(p)]
