        want = exp["correct"] + drilled.get(cid, 0)
        if str(exp["state"]) == "stable":
            if str(v.state) != "stable":
                p7_bad.append(f"{cid}: stable state REGRESSED to {v.state} (no regressions)")
        else:
            if str(v.state) != str(exp["state"]) and str(v.state) != "stable":
                p7_bad.append(f"{cid}: state changed {exp['state']} -> {v.state} (only -> stable is sanctioned)")
            elif str(v.state) == "stable" and str(exp["state"]) != "stable":
                improved.append(cid)
        if v.correct_derivations != want:
            p7_bad.append(
                f"{cid}: correct derivations {v.correct_derivations} != frozen {want} (base {exp['correct']} + drill {drilled.get(cid, 0)})"
            )
    for cid, e in FROZEN["mastery_expected"].items():
        v = mv.get(cid)
        if v is None:
            p7_bad.append(f"{cid}: the mastery-expected concept left the view")
            continue
        if v.state != e["state"]:
            p7_bad.append(f"{cid}: state {v.state} != {e['state']}")
        if v.correct_derivations != e["correct"]:
