from pathlib import Path
from kainos.tutor.session import load_store

store = load_store(Path("results/phase-6/e6.24-run1/codeX-S04.json"))

# raw mastery-event counts per concept (the store's own bytes)
events = {}
for a in store.query():
    ctx = a.context.data if a.context else {}
    if ctx.get("kind") == "mastery-event":
        # event: subject concept, object letter/verdict
        subj = a.subject if isinstance(a.subject, str) else str(a.subject)
        obj = a.object if isinstance(a.object, str) else str(a.object)
        slug = subj.split(":")[-1]
        events.setdefault(slug, []).append(obj)

def state_of(slug, prereqs, K=4):
    evs = events.get(slug, [])
    correct = sum(1 for e in evs if "correct" in e) or sum(1 for e in evs if e == "T")
    letters = {}
    for e in evs:
        letters[e] = letters.get(e, 0) + 1
    gaps = [p for p in prereqs if state_of(p, prereqs.get(p, ()), K) != "stable"]
    if correct < 1:
        st = "exposed"
    elif correct >= K and not gaps:
        st = "stable"
    else:
        st = "practicing"
    return st, correct, gaps

# prereq facts from the store
prereqs = {}
for a in store.query():
    ctx = a.context.data if a.context else {}
    if ctx.get("kind") == "prereq":
        s = a.subject.split(":")[-1]
        o = a.object.split(":")[-1]
        prereqs.setdefault(s, set()).add(o)

