    evs = events.get(slug)
    if not evs:
        print(f"  {slug:18s}: NO mastery events")
        continue
    from collections import Counter
    c = Counter(evs)
    correct = c.get("derivation-correct", c.get("T", 0))
    pr = prereqs.get(slug, set())
