            elif (a, b) == (41, 71):
                assert g == 1 and st == 7
                ans = (
                    f"forty-one and seventy-one: a coprime pair — they share no part above one, and the reduction "
                    f"chain walks seven steps, the ceiling of my line, at the line end {end}"
